"""
BNI大台南南區分會網站後台。跑法：python app.py（預設 port 5063）
公開頁：/ 分會列表、/<slug> 分會頁面
後台：/admin（帳密登入），各分會資訊管理員用同一組帳密登入後可編輯簡介、
參訪須知、分會之光數據、社群連結，且這三類都能自行新增/刪除欄目。
"""
import os
from functools import wraps

from flask import Flask, abort, redirect, render_template, request, session, url_for
from werkzeug.security import check_password_hash

import db

app = Flask(__name__)
app.secret_key = os.environ.get("BNI_CHAPTERS_SECRET_KEY", "")
ADMIN_USER = os.environ.get("BNI_CHAPTERS_ADMIN_USER", "")
ADMIN_PASSWORD_HASH = os.environ.get("BNI_CHAPTERS_ADMIN_PASSWORD_HASH", "")

db.init_db()


def login_required(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        if not session.get("admin"):
            return redirect(url_for("admin_login", next=request.path))
        return view(*args, **kwargs)

    return wrapped


# ---------- 公開頁 ----------

@app.route("/")
def index():
    conn = db.get_conn()
    chapters = db.list_chapters(conn)
    conn.close()
    return render_template("index.html", chapters=chapters)


@app.route("/<slug>")
def chapter_page(slug):
    conn = db.get_conn()
    chapter = db.get_chapter_by_slug(conn, slug)
    if not chapter:
        conn.close()
        abort(404)
    notices = db.get_notices(conn, chapter["id"])
