"""
BNI大台南南區分會網站後台。跑法：python app.py（預設 port 5063）
公開頁：/ 分會列表、/<slug> 分會頁面
後台：/admin（帳密登入），各分會資訊管理員用同一組帳密登入後可編輯簡介、
參訪須知、分會之光數據、社群連結，且這三類都能自行新增/刪除欄目。
"""
import os
from functools import wraps

from flask import Flask, abort, redirect, render_template, request, session, url_for
from werkzeug.security import check_password_hash

import db

app = Flask(__name__)
app.secret_key = os.environ.get("BNI_CHAPTERS_SECRET_KEY", "")
ADMIN_USER = os.environ.get("BNI_CHAPTERS_ADMIN_USER", "")
ADMIN_PASSWORD_HASH = os.environ.get("BNI_CHAPTERS_ADMIN_PASSWORD_HASH", "")

db.init_db()


def login_required(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        if not session.get("admin"):
            return redirect(url_for("admin_login", next=request.path))
        return view(*args, **kwargs)

    return wrapped


# ---------- 公開頁 ----------

@app.route("/")
def index():
    conn = db.get_conn()
    chapters = db.list_chapters(conn)
    conn.close()
    return render_template("index.html", chapters=chapters)


@app.route("/<slug>")
def chapter_page(slug):
    conn = db.get_conn()
    chapter = db.get_chapter_by_slug(conn, slug)
    if not chapter:
        conn.close()
        abort(404)
    notices = db.get_notices(conn, chapter["id"])
    values = db.get_values(conn, chapter["id"])
    stats = db.get_stats(conn, chapter["id"])
    links = db.get_links(conn, chapter["id"])
    conn.close()
    return render_template(
        "chapter.html",
        chapter=chapter,
        notices=notices,
        values=values,
        stats=stats,
        links=links,
    )


# ---------- 後台登入 ----------

@app.route("/admin/login", methods=["GET", "POST"])
def admin_login():
    error = None
    if request.method == "POST":
        username = request.form.get("username", "")
        password = request.form.get("password", "")
        if username == ADMIN_USER and ADMIN_PASSWORD_HASH and check_password_hash(
            ADMIN_PASSWORD_HASH, password
        ):
            session["admin"] = True
            next_url = request.args.get("next") or url_for("admin_list")
            return redirect(next_url)
        error = "帳號或密碼錯誤"
    return render_template("login.html", error=error)


@app.route("/admin/logout")
def admin_logout():
    session.pop("admin", None)
    return redirect(url_for("admin_login"))


# ---------- 後台管理 ----------

